args.sql:
SELECT COUNT(*) FROM (
    SELECT interact_fan_pivot
    FROM interactions
    GROUP BY interact_fan_pivot
    HAVING SUM(CASE WHEN chat_activity->>'Msg_Tone' = 'Negative' THEN 1 ELSE 0 END)::numeric / COUNT(*)::numeric >= 0.7
) t;

SELECT COUNT(*) FROM interactions i WHERE i.interact_fan_pivot IN (
    SELECT interact_fan_pivot
    FROM interactions
    GROUP BY interact_fan_pivot
    HAVING SUM(CASE WHEN chat_activity->>'Msg_Tone' = 'Negative' THEN 1 ELSE 0 END)::numeric / COUNT(*)::numeric > 0.7
);

SELECT COUNT(*) FROM interactions i WHERE i.interact_fan_pivot IN (
    SELECT interact_fan_pivot
    FROM interactions
    GROUP BY interact_fan_pivot
    HAVING SUM(CASE WHEN chat_activity->>'Msg_Tone' = 'Negative' THEN 1 ELSE 0 END)::numeric / COUNT(*)::numeric >= 0.7
);

SELECT COUNT(*) FROM (
    SELECT interact_fan_pivot
    FROM interactions
    GROUP BY interact_fan_pivot
    HAVING SUM(CASE WHEN chat_activity->>'Msg_Tone' = 'Negative' THEN 1 ELSE 0 END) = COUNT(*)
) t;

SELECT COUNT(*) FROM (
    SELECT i.*
    FROM interactions i
    WHERE i.interact_fan_pivot IN (
        SELECT interact_fan_pivot
        FROM interactions
        GROUP BY interact_fan_pivot
        HAVING SUM(CASE WHEN chat_activity->>'Msg_Tone' = 'Negative' THEN 1 ELSE 0 END) = COUNT(*)
    )
) t;

SELECT COUNT(*) FROM (
    SELECT DISTINCT i.interact_fan_pivot
    FROM interactions i
    JOIN moderationandcompliance m ON i.activity_reg = m.moderation_interact_pivot
    WHERE m.mod_stat IN ('Warning', 'Restricted')
) t;

SELECT COUNT(*) FROM (
    SELECT interact_fan_pivot
    FROM interactions
    WHERE chat_activity->>'Msg_Tone' = 'Negative'
    AND interact_fan_pivot NOT IN (
        SELECT interact_fan_pivot 
        FROM interactions 
        WHERE chat_activity->>'Msg_Tone' != 'Negative'
    )
) t;

SELECT COUNT(*) FROM (
    SELECT interact_fan_pivot,
           SUM(CASE WHEN chat_activity->>'Msg_Tone' = 'Negative' THEN 1 ELSE 0 END)::numeric / COUNT(*)::numeric as pct
    FROM interactions
    GROUP BY interact_fan_pivot
) t WHERE pct <= 0.7 AND pct > 0.5;

SELECT COUNT(*) FROM (
    SELECT interact_fan_pivot
    FROM interactions
    WHERE chat_activity->>'Msg_Tone' != 'Negative'
    AND interact_fan_pivot NOT IN (
        SELECT interact_fan_pivot 
        FROM interactions 
        WHERE chat_activity->>'Msg_Tone' = 'Negative'
    )
) t;
